#!/usr/bin/env python3
"""Build the install plan from checked boxes without installing anything."""
import json, pathlib, re
root=pathlib.Path(__file__).resolve().parents[1]
p=root/'CHECKLIST.md'
text=re.sub(r'\[\s*[xX]\s*\]', '[x]', p.read_text())
p.write_text(text)
selected=[]; section=''
for line in text.splitlines():
    if line.startswith('## '): section=line[3:]
    if line.startswith('- [x] '): selected.append({'section':section,'item':line[6:]})
# Only mappings verified against Homebrew metadata. Unknown apps stay explicit.
app_casks={'Blip':'blip','ChatGPT':'chatgpt','CleanShot X':'cleanshot','DisplayLink Manager':'displaylink','Ghostty':'ghostty','Jump Desktop':'jump-desktop','Parsec':'parsec','Presentify':'presentify','Raycast':'raycast','Tailscale':'tailscale-app','Notchy':'vishvavariya/notchy/notchy'}
formulas=set(); casks=set(); manual=[]
for s in selected:
    item=s['item']; section=s['section']
    if section=='Applications found':
        name=re.search(r'\*\*(.+?)\*\*',item).group(1)
        if name in app_casks: casks.add(app_casks[name])
        else: manual.append(name)
    elif section=='Homebrew casks': casks.add(re.search(r'`([^`]+)`',item).group(1))
    elif section.startswith('Homebrew formulae') or section=='Other installed Homebrew formulae': formulas.add(re.search(r'`([^`]+)`',item).group(1))
    elif item=='Git and GitHub CLI, then sign in again': formulas.update(['git','gh'])
assert all(re.fullmatch(r'[A-Za-z0-9@+_./-]+',n) for n in formulas|casks)
brewfile=['# Generated by scripts/prepare.py from CHECKLIST.md.','# Re-run preparation after changing your selections.']
brewfile += [f'brew "{n}"' for n in sorted(formulas)]
brewfile += [f'cask "{n}"' for n in sorted(casks)]
(root/'Brewfile.selected').write_text('\n'.join(brewfile)+'\n')
(root/'inventory/selected.json').write_text(json.dumps({'checked_items':selected,'formulae':sorted(formulas),'casks':sorted(casks),'manual_apps':manual},indent=2)+'\n')
notes={'Ardia':'Original app: com.ardia.browser. Confirm the official installer with the owner; do not substitute another browser.','ArtCraft Launcher':'Original app: ai.storyteller.artcraft-launcher. Confirm the official Storyteller/ArtCraft source; similarly named projects exist.','Card Hopper':'Original app: com.cardhopper.app. Obtain from the original developer or purchase history.','Grok Bot':'Original bundle ID is com.anysphere.sand. The name alone is ambiguous; confirm the original source with the owner. Do not substitute a similarly named app.','Isocast':'Original app: dev.isocast.release. Obtain the original developer installer.','Magnet':'Original app: com.crowdcafe.windowmagnet. Restore through Mac App Store purchase history.','Notchy':'Original app: dev.notchy.app. Official installation help: https://notchy.dev/help/install-notchy/','UGREEN NAS':'Original app: com.ugreen.pro.client. Obtain the Mac client from the official UGREEN NAS support/download site and sign in again.'}
lines=['# Selected applications requiring manual installation','','These selections are preserved even though they are absent from the automatic Brewfile. Confirm official sources and required licenses before installing.','']
lines += [f'- [ ] **{n}** — {notes.get(n,"Confirm the official installer with the owner.")}' for n in manual]
lines += ['','## Setup tasks','','- Install Xcode command-line tools if absent (`xcode-select --install`). Full Xcode was not selected.','- Sign in to GitHub, purchased apps, Tailscale, NAS, and other accounts as needed.','- Browser bookmarks and Keychain/iCloud sync require the owner’s account.','- Configure and verify backups and FileVault with the owner.','- Shell preferences, font, and editor were selected as general goals, but no specific configuration files, font, editor app, or extensions were checked. Ask for those choices before adding them.','- The selected `codex` cask is the Codex CLI. It is not the Codex desktop app.','- No settings contents, licenses, passwords, app binaries, or private files are included.','']
(root/'MANUAL-INSTALL.md').write_text('\n'.join(lines))
print(f'Prepared {len(formulas)} formulae, {len(casks)} casks, and {len(manual)} manual apps.')
